from duration import parse_duration

valid = {
    "250ms": 250,
    "2s": 2000,
    "3m": 180000,
    "1h": 3600000,
    "0ms": 0,
    "0s": 0,
    "90s": 90000,
}

malformed = [
    "-2s", "-250ms", "2sfoo", "2 s", " 2s", "2s ", "", "s", "ms",
    "2.5s", "+2s", "2", "1d", "2ss", "1m30s", "NaN", None, 250, "2S", "2MS",
]

for text, expected in valid.items():
    got = parse_duration(text)
    assert got == expected, (text, got, expected)

for text in malformed:
    try:
        parse_duration(text)
    except ValueError:
        pass
    else:
        raise AssertionError(f"expected ValueError for {text!r}")

print("all validation checks passed")
